const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:ROAM_ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function datePlus(date,days){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10);}
function nextWeek(){const d=new Date(today()+'T12:00:00Z');const delta=((8-d.getUTCDay())%7)||7;const start=datePlus(today(),delta);return{start,end:datePlus(start,6)};}
function dateLabel(date){return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'));}
function eventLabel(p){return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:'America/Denver'}).format(new Date(p.start))+' MT';}
function activeTrip(){return companion.trips.find(t=>t.id===companion.activeTrip)||null;}
function plannedOrigin(){const t=activeTrip();return state.view==='trips'&&t?locations[t.area==='Colorado'?'Boulder':t.area]:state.location;}
function recommendationDistance(p){return distance(plannedOrigin(),p);}
function replyFor(id){return companion.reactions[id];}
score=p=>{let value=oldScore(p);const a=companion.answers;if(a.crowds==='Quiet corners'&&p.event&&p.eventKind==='music')value-=18;if(a.energy==='Keep it gentle'&&p.pace==='Active')value-=14;if(a.daytime==='Evenings'&&p.event&&new Date(p.start).getUTCHours()<20)value-=8;const r=replyFor(p.id);if(r?.feeling==='yes')value+=22;if(r?.reason==='cost'&&p.price==='$$')value-=15;if(r?.reason==='distance')value-=recommendationDistance(p);if(p.genre&&a.genres?.includes(p.genre))value+=25;if(p.event&&a.eventStyle==='Outdoor music'&&p.eventKind==='music')value+=10;if(p.event&&a.eventStyle==='An intimate local show')value-=8;if(p.pace==='Active'&&a.trail==='A gentle scenic stroll')value-=8;if(p.id==='trident'&&a.coffee?.includes('Books to browse'))value+=20;if(p.price==='Free'&&a.budget==='Budget friendly')value+=10;for(const [id,reaction] of Object.entries(companion.reactions)){const previous=places.find(x=>x.id===id);if(!previous||id===p.id)continue;if(reaction.feeling==='no'&&reaction.reason==='taste')value-=p.tags.filter(t=>previous.tags.includes(t)).length*3;if(reaction.reason==='cost'&&p.price==='$$')value-=8;if(reaction.reason==='crowds'&&p.event&&p.eventKind==='music')value-=10;}return value;};
recommendations=()=>{
 const trip=state.view==='trips'?activeTrip():null;
 if(state.view==='trips'&&!trip)return[];
 const start=trip?trip.start:today(),end=trip?trip.end:datePlus(today(),7);
 let candidates=places.filter(p=>{
  if(p.sample)return false;
  if(state.view==='saved'&&!state.saved.includes(p.id))return false;
  if(state.view!=='saved'&&recommendationDistance(p)>(trip?(trip.area==='Colorado'?100:50):state.radius))return false;
  if(p.event&&(p.eventDate<start||p.eventDate>end||new Date(p.start).getTime()+4*3600000<Date.now()))return false;
  if(state.category!=='For you'&&p.category!==state.category)return false;
  if(state.mood!=='Open to anything'&&state.view==='discover'&&!p.moods.includes(state.mood))return false;
  if(state.query&&!`${p.name} ${p.city} ${p.tags.join(' ')}`.toLowerCase().includes(state.query.toLowerCase()))return false;
  if(state.view==='route'&&state.route&&detourMinutes(p)>state.profile.detour)return false;
  const reaction=replyFor(p.id);if(state.view!=='saved'&&reaction?.feeling==='no'&&reaction.reason==='taste')return false;
  if(state.view!=='saved'&&reaction?.feeling==='later'&&Date.now()-reaction.at<24*3600000)return false;
  return true;
 });
 candidates.sort((a,b)=>state.sort==='distance'?recommendationDistance(a)-recommendationDistance(b):score(b)-score(a));
 return candidates;
};
