function matchReason(p){const common=p.tags.filter(t=>state.profile.interests.includes(t));const a=companion.answers;if(p.id==='trident'&&a.coffee?.includes('Books to browse'))return'You said a good coffee and books make a perfect pause.';if(p.pace==='Slow'&&a.energy==='A quiet stop before heading home')return'A quieter stop, just how you like to wind down.';if(p.event)return`${common.length?'Fits your interest in '+common.join(' and ').toLowerCase()+'.':'Something different to try.'} ${eventLabel(p)}.`;return common.length?`Because you like ${common.join(' and ').toLowerCase()}.`:p.reason;}
