function renderCompanionHome(){const recs=recommendations();const candidate=recs.find(p=>p.id==='trident'&&companion.answers.coffee?.includes('Books to browse'))||recs[0];$('#companion-feature').innerHTML=candidate?`<div class="companion-image">${photoMarkup(candidate,false)}</div><div class="companion-message"><div class="detail-kind">A THOUGHT FOR YOUR JOURNEY</div><h2>${candidate.event?'An evening worth keeping free.':candidate.pace==='Slow'?'A good moment for a little pause.':'Something I think you’ll enjoy.'}</h2><p class="companion-voice">${matchReason(candidate)}</p><button class="suggestion-name" data-detail="${candidate.id}">${escapeHTML(candidate.name)} ${icon('arrow-up-right')}</button><span class="suggestion-context">${candidate.event?eventLabel(candidate)+' · ':''}${distLabel(candidate)} · ${candidate.price}</span>${responseButtons(candidate.id)}</div>`:`<div class="companion-message"><div class="detail-kind">HERE WHEN YOU NEED ME</div><h2>Let’s find your kind of moment.</h2><p>Choose your current location or a confirmed destination, then refresh nearby places. Event coverage is shown on the Events page.</p><button class="dark-button" data-view="trips">Plan ahead ${icon('arrow-right')}</button></div>`;}
renderFeed=()=>{if(state.view==='route'&&!state.route){$('#feed').innerHTML='<div class="empty-state"><h3>A companion for your route.</h3><p>Share a Google Maps destination or choose one above. I’ll remember it until you clear it.</p></div>';return;}const recs=recommendations();$('#feed').innerHTML=recs.length?recs.slice(0,window.RoamFocus?.limit()??18).map(p=>`<article class="place-card"><div class="card-image-wrap"><button data-detail="${p.id}" aria-label="Read about ${escapeHTML(p.name)}">${photoMarkup(p)}</button><span class="card-badge">${icon(p.event?'music':'sparkles')}${p.event?'EVENT · '+dateLabel(p.eventDate):p.badge}</span><button class="save-button" data-save="${p.id}" aria-label="Save ${escapeHTML(p.name)}">${icon('bookmark')}</button></div><div class="card-body"><div class="card-meta"><span class="card-category">${escapeHTML(p.category)} · ${escapeHTML(p.city)}</span><span class="card-distance">${icon('pin')}${recommendationDistance(p).toFixed(1)} mi ${state.view==='trips'?'from trip base':'away'}</span></div><button class="place-title" data-detail="${p.id}">${escapeHTML(p.name)}</button><p>${p.event?eventLabel(p)+' · Red Rocks Amphitheatre':p.description}</p><div class="reason">${icon('sparkles')}${escapeHTML(matchReason(p))}</div>${responseButtons(p.id)}<div class="card-bottom"><span>${p.event?'Official calendar · checked '+p.checkedAt:p.price}</span><button data-detail="${p.id}">More details ${icon('arrow-up-right')}</button></div></div></article>`).join(''):`<div class="empty-state"><h3>${state.view==='saved'?'Your saved moments live here.':state.category==='Events'?'No dated events match just now.':'Nothing quite right here yet.'}</h3><p>${state.category==='Events'?'Try your trip dates or a wider area. Listings come from Red Rocks’ official calendar; coverage is limited.':state.view==='trips'?'Try different dates or another Colorado area.':'Change your mood, filters, or Colorado area.'}</p><button class="dark-button" data-view="trips">Look ahead to a trip ${icon('arrow-right')}</button></div>`;updateSaved();if(state.view==='discover')renderCompanionHome();};
render=()=>{const custom=['trips','inbox'].includes(state.view);oldRender();$('#trips-panel').hidden=state.view!=='trips';$('#inbox-panel').hidden=state.view!=='inbox';$('#companion-status').hidden=state.view!=='discover';$('#profile-panel').hidden=state.view!=='profile';$('#feed-section').hidden=['profile','inbox'].includes(state.view);$('#personalize').hidden=state.view==='profile';$('.eyebrow').textContent='YOUR PERSONAL TRAVEL COMPANION';if(state.view==='discover'){$('#page-title').textContent=companion.answers.name?`With you, ${companion.answers.name}.`:'With you, along the way.';$('#page-subtitle').textContent='Your tastes, your mood, your journey. I’ll keep an eye out for what fits.';$('#feed-title').textContent='Places and moments for you';$('#feed-subtitle').textContent='Tell me how these feel. Your next suggestions will reflect it.';$('#companion-status').innerHTML=`<button data-companion="setup"><span>${icon('sparkles')}Your travel style</span><strong>${companion.setupComplete?'Getting to know you':'Let’s get to know you'}</strong><small>${companion.setupComplete?Object.keys(companion.answers).length+' answers · always evolving':'A thoughtful introduction, at your pace'}</small></button><button data-view="route"><span>${icon('route')}On your way</span><strong>${companion.route?escapeHTML(companion.route.name):'No shared route yet'}</strong><small>${companion.route?'Remembered on this device':'Google Maps sharing · manual planning'}</small></button><button data-view="trips"><span>${icon('sun')}Looking ahead</span><strong>${companion.trips.length?companion.trips.length+' upcoming plan'+(companion.trips.length===1?'':'s'):'Where to next?'}</strong><small>Places + events that fit your dates</small></button>`;renderCompanionHome();}else if(state.view==='route'){$('#page-title').textContent='I’m along for the ride.';$('#page-subtitle').textContent='A remembered destination, with room for a worthwhile stop.';}else if(state.view==='profile'){$('#page-title').textContent='A companion that gets you.';$('#page-subtitle').textContent='Your introduction, your changing tastes, and what you’ve told me.';renderCompanionProfile();}else if(state.view==='trips'){$('#page-title').textContent='Let’s look ahead together.';$('#page-subtitle').textContent='Your upcoming trips, with places and events chosen around your dates.';renderTrips();$('#feed-title').textContent=activeTrip()?'For '+activeTrip().name:'Choose a trip to see suggestions';$('#feed-subtitle').textContent=activeTrip()?dateLabel(activeTrip().start)+'–'+dateLabel(activeTrip().end)+' · events filtered to these dates':'Plan a destination and travel dates above.';$('#radius-button').hidden=true;renderCategories();renderFeed();}else if(state.view==='inbox'){$('#page-title').textContent='A little conversation, ongoing.';$('#page-subtitle').textContent='Suggestions I’ve made and what you thought of them.';renderInbox();}document.querySelectorAll('.nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);if(b.dataset.view===state.view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#inbox-count').textContent=companion.inbox.length;};
changeView=view=>{if(!['discover','saved','route','profile','trips','inbox'].includes(view))return;state.view=view;state.category='For you';state.query='';$('#search').value='';render();window.scrollTo({top:0,behavior:'smooth'});};
function renderCompanionProfile(){oldRenderProfile();$('#profile-panel').insertAdjacentHTML('afterbegin',`<div class="profile-summary"><div><h2>${companion.setupComplete?'A picture of you, so far.':'Let’s go beyond a few favorites.'}</h2><p>${Object.keys(companion.answers).length} introduction answers · ${Object.keys(companion.reactions).length} suggestion responses</p></div><button class="dark-button" data-companion="setup">${companion.setupComplete?'Revisit my introduction':'Continue my introduction'} ${icon('sparkles')}</button></div>`);$('.profile-note').innerHTML=`${icon('heart')}<h2>Your feelings are useful.</h2><p>“Not now” means the timing was wrong. “Not my thing” tells me the taste was wrong. You can also tell me about distance, cost, crowds, or anything I missed.</p><p>Dietary and access preferences are remembered, but venue suitability still needs to be checked.</p><button class="outline-button" data-view="inbox">See our conversation ${icon('arrow-right')}</button>`;}
function tripDialog(id){const existing=companion.trips.find(t=>t.id===id),range=nextWeek();openDialog(`<div class="dialog-inner"><div class="detail-kind">AHEAD OF THE JOURNEY</div><h2>${existing?'Update your trip.':'What’s coming up?'}</h2><label class="form-label" for="trip-name">Trip name</label><input id="trip-name" class="form-input" maxlength="70" value="${escapeHTML(existing?.name||'My Colorado trip')}" placeholder="A week in Colorado"><label class="form-label" for="trip-area">Destination area</label><select id="trip-area" class="form-select">${['Colorado','Boulder','Denver','Golden'].map(a=>`<option ${a===existing?.area?'selected':''}>${a}</option>`).join('')}</select><div class="route-fields"><div><label class="form-label" for="trip-start">Arriving</label><input type="date" id="trip-start" class="form-input" min="${today()}" value="${existing?.start||range.start}"></div><div><label class="form-label" for="trip-end">Leaving</label><input type="date" id="trip-end" class="form-input" min="${today()}" value="${existing?.end||range.end}"></div></div><p class="fine-print">Trip distances use your destination area, while nearby suggestions keep using your current location. This version covers Colorado.</p><button class="dark-button full-button" data-companion="save-trip" data-trip-id="${id||''}">Save trip ${icon('check')}</button></div>`);}
function saveTrip(id){const name=$('#trip-name').value.trim(),area=$('#trip-area').value,start=$('#trip-start').value,end=$('#trip-end').value;if(!name||!start||!end||start>end||start<today()){toast('Add a name and valid upcoming dates. Leaving must be after arriving.');return;}const trip={id:id||crypto.randomUUID(),name,area,start,end};const index=companion.trips.findIndex(t=>t.id===id);if(index>=0)companion.trips[index]=trip;else companion.trips.push(trip);companion.activeTrip=trip.id;persist();$('#dialog').close();changeView('trips');toast('Your trip is saved. View ideas whenever you’re ready.');}
function renderTrips(){$('#trips-panel').innerHTML=`<div class="trip-toolbar"><p>There’s room for a plan and a little spontaneity.</p><button class="dark-button" data-companion="new-trip">${icon('sun')}Add an upcoming trip</button></div><div class="trip-list">${companion.trips.length?companion.trips.map(t=>`<article class="trip-card ${t.id===companion.activeTrip?'active':''}"><button class="trip-select" data-select-trip="${t.id}"><span class="detail-kind">${escapeHTML(t.area)}</span><h3>${escapeHTML(t.name)}</h3><p>${dateLabel(t.start)}–${dateLabel(t.end)} · ${t.start.slice(0,4)}</p></button><div class="trip-actions"><button data-edit-trip="${t.id}">Edit</button><button data-delete-trip="${t.id}">Remove</button></div></article>`).join(''):`<div class="trip-empty"><h3>A place to look forward to.</h3><p>Add travel dates to see scheduled events alongside places you might enjoy.</p><button class="outline-button" data-companion="new-trip">Start with my Colorado trip ${icon('arrow-right')}</button></div>`}</div><div class="source-status">${icon('music')} ${companion.eventStatus==='loading'?'Checking the saved event calendar…':companion.eventStatus==='error'?'Event listings couldn’t load. Places are still available.':'Official Red Rocks event listings · checked October 3, 2026 · verify changes with the organizer'}</div>`;}
function parseMapsDestination(text){const raw=text.trim();const urls=raw.match(/https?:\/\/[^\s]+/g)||[];for(const link of urls){let url;try{url=new URL(link);}catch{continue;}if(!['www.google.com','google.com','maps.google.com','maps.app.goo.gl','goo.gl'].includes(url.hostname))continue;if(['maps.app.goo.gl','goo.gl'].includes(url.hostname))return{unsupported:true};let value=url.searchParams.get('destination')||url.searchParams.get('daddr')||url.searchParams.get('q')||url.searchParams.get('query');const path=url.pathname.match(/\/dir\/(?:[^/]+\/)?([^/]+)\/?$/);if(!value&&path)value=decodeURIComponent(path[1]);if(!value){const coords=url.pathname.match(/!3d(-?\d+(?:\.\d+)?)!4d(-?\d+(?:\.\d+)?)/);if(coords)return{lat:+coords[1],lng:+coords[2],name:'Shared Maps destination'};}if(value){const coords=value.match(/^(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)$/);if(coords&&Math.abs(+coords[1])<=90&&Math.abs(+coords[2])<=180)return{lat:+coords[1],lng:+coords[2],name:'Shared Maps destination'};const decoded=value.replace(/\+/g,' ');const city=Object.keys(locations).find(key=>decoded.toLowerCase().includes(key.toLowerCase()));if(city)return{...locations[city],name:decoded,approximate:true};return{address:decoded};}}const direct=raw.match(/^(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)$/);if(direct&&Math.abs(+direct[1])<=90&&Math.abs(+direct[2])<=180)return{lat:+direct[1],lng:+direct[2],name:'My destination'};const city=Object.keys(locations).find(key=>raw.toLowerCase()===key.toLowerCase());return city?locations[city]:{address:raw};}
renderRoute=()=>{$('#route-panel').innerHTML=`<div><div class="detail-kind">ON YOUR WAY</div><h2>${companion.route?'I remember where you’re heading.':'Bring your route along.'}</h2><p>${companion.route?escapeHTML(companion.route.name):'Choose a destination or share a full Google Maps destination link. You won’t need to re-enter a remembered route.'}</p><div class="connection-note">${icon('route')}<div><strong>Google Maps automatic awareness</strong><span>Not connected in this web version. The Android app needs navigation inside Roam to reliably know each destination.</span></div></div><p class="fine-print">Android: install Roam from your browser, then choose it in the share sheet where available. Short Maps links need a full destination link or an area selected below.</p></div><div><label class="form-label" for="maps-link">Google Maps destination link or coordinates</label><input id="maps-link" class="form-input" type="text" placeholder="https://www.google.com/maps/dir/?…" value=""><button class="outline-button" data-companion="import-route">Use this destination ${icon('route')}</button><label class="form-label" for="destination">Or plan a destination ahead of time</label><select id="destination" class="form-select">${Object.entries(locations).map(([key,l])=>`<option value="${key}" ${state.route?.name===l.name?'selected':''}>${key}, Colorado</option>`).join('')}</select><button class="dark-button full-button" data-companion="remember-route">Find stops along the way ${icon('arrow-right')}</button>${companion.route?`<div class="route-status">Up to ${state.profile.detour} extra minutes · geographic estimate${companion.route.approximate?' · destination area, not exact address':''}</div><a class="maps-link" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination=${companion.route.lat},${companion.route.lng}">Open route in Google Maps ${icon('arrow-up-right')}</a><button class="route-clear" data-companion="clear-route">Clear remembered destination</button>`:''}</div>`;};
function importRoute(text){if(!text.trim()){toast('Paste a destination link or coordinates first.');return false;}const dest=parseMapsDestination(text);if(dest.unsupported){toast('That’s a short Maps link. Use a full destination link or select the destination area.');return false;}if(dest.address){toast('This address needs geocoding. Use destination coordinates or choose a Colorado area.');return false;}companion.route=dest;state.route=dest;persist();changeView('route');toast(dest.approximate?'Destination area remembered. Detours are approximate.':'Destination remembered. I’ll keep it for this route.');return true;}
function ensureSuggestion(p,context='A suggestion for you'){let item=companion.inbox.find(i=>i.placeId===p.id);if(!item){item={id:crypto.randomUUID(),placeId:p.id,name:p.name,context,createdAt:Date.now()};companion.inbox.unshift(item);companion.inbox=companion.inbox.slice(0,100);companionSave();}return item;}
function recordResponse(id,feeling,reason='',note=''){const p=places.find(p=>p.id===id);if(!p)return false;if(!['yes','later','no'].includes(feeling))return false;const text=note.slice(0,600);if(!reason&&feeling==='no')reason='taste';companion.reactions[id]={feeling,reason,note:text,at:Date.now()};const item=ensureSuggestion(p);item.response=feeling;item.reason=reason;item.note=text;item.respondedAt=Date.now();if(feeling==='yes'){state.feedback[id]=1;if(!state.saved.includes(id))state.saved.push(id);}else if(feeling==='no'&&reason==='taste')state.feedback[id]=-1;else if(feeling==='later')delete state.feedback[id];persist();render();toast(feeling==='yes'?'Saved. I’ll remember that this felt right.':feeling==='later'?'I’ll leave this one for another day. Your tastes haven’t changed.':'Thanks for telling me. I’ll keep that in mind.');return true;}
function reactionDialog(id,feeling='no'){const p=places.find(x=>x.id===id);if(!p)return;openDialog(`<div class="dialog-inner"><div class="detail-kind">I’M LISTENING</div><h2>How does this suggestion feel?</h2><p>${escapeHTML(p.name)}</p><label class="form-label" for="reaction-feeling">Your reaction</label><select id="reaction-feeling" class="form-select"><option value="yes" ${feeling==='yes'?'selected':''}>Sounds good</option><option value="later" ${feeling==='later'?'selected':''}>Not right now</option><option value="no" ${feeling==='no'?'selected':''}>Doesn’t feel right</option></select><label class="form-label" for="reaction-reason">What should I understand?</label><select id="reaction-reason" class="form-select"><option value="taste">It’s not my kind of thing</option><option value="timing">The timing or my energy</option><option value="distance">Too far out of the way</option><option value="cost">More than I want to spend</option><option value="crowds">The atmosphere or crowds</option><option value="other">Something else</option></select><label class="form-label" for="reaction-note">Anything else you’d like to tell me?</label><textarea id="reaction-note" class="form-input" rows="3" maxlength="600" placeholder="I love this kind of place, but today I need something quieter…">${escapeHTML(replyFor(id)?.note||'')}</textarea><button class="dark-button full-button" data-companion="save-response" data-place-id="${id}">Tell my companion ${icon('heart')}</button><p class="fine-print">Your explicit reactions refine ranking. Personal notes are remembered with the suggestion.</p></div>`);}
details=id=>{const p=places.find(p=>p.id===id);if(!p)return;const nav=`https://www.google.com/maps/dir/?api=1&destination=${!p.live&&p.address?encodeURIComponent(p.address):p.lat+','+p.lng}`;ensureSuggestion(p,'You took a closer look');openDialog(`<section id="place-gallery" class="photo-gallery" aria-label="Place photos"></section><div class="dialog-inner"><div class="detail-kind">${escapeHTML(p.category)} · ${escapeHTML(p.city)}</div><h2>${escapeHTML(p.name)}</h2><div class="detail-stats"><span>${icon('pin')}${recommendationDistance(p).toFixed(1)} mi ${state.view==='trips'?'from trip base':'away'}</span>${p.event?`<span>${icon('clock')}${eventLabel(p)}</span>`:`<span>${p.price} · ${p.pace} pace</span>`}</div><p class="detail-description">${escapeHTML(p.details)}</p>${p.unlisted?'<p class="availability-note conflict">This event is cancelled, postponed, or no longer in the refreshed calendar. Check the organizer before planning.</p>':''}<div class="detail-reason">${icon('sparkles')} ${escapeHTML(matchReason(p))}</div>${p.runtimePhoto&&p.website?`<a class="official-event-link" href="${escapeHTML(p.website)}" target="_blank" rel="noopener">${escapeHTML(p.booking)} ${icon('arrow-up-right')}</a><p class="fine-print">Source: ${escapeHTML(p.source||'Venue website')} · checked ${p.live?new Date(p.checkedAt).toLocaleDateString():p.checkedAt}. Check current availability and activity requirements directly.</p>`:''}${p.event?`<a class="official-event-link" href="${escapeHTML(p.sourceURL)}" target="_blank" rel="noopener noreferrer">Official event details & tickets ${icon('arrow-up-right')}</a><p class="fine-print">Source: ${p.source} · checked ${p.checkedAt}. This is an official-calendar listing; ticket availability is checked with the organizer. Times are in Mountain Time.</p>`:''}${companion.answers.diet?.length||companion.answers.accessibility?.length?'<p class="preference-reminder">I remember your food and access preferences. Suitability here hasn’t been verified; check directly with the venue.</p>':''}<div class="detail-actions"><a class="dark-button" data-navigation="${p.id}" href="${nav}" target="_blank" rel="noopener noreferrer">Navigate there ${icon('arrow-up-right')}</a><button class="outline-button" data-save="${p.id}">${icon('bookmark')}Save for later</button></div>${p.event&&(p.image||p.imageURL)?`<details class="event-artwork"><summary>Official event poster</summary><img class="event-poster" src="${escapeHTML(p.imageURL||'assets/'+p.image+'.jpg')}" alt="Official event poster for ${escapeHTML(p.name)}" loading="lazy"></details>`:''}<h3 class="reaction-heading">How does this feel to you?</h3>${responseButtons(p.id)}<button class="text-button" data-response-detail="${p.id}">Tell me a little more</button><p class="fine-print">Event artwork comes from the official calendar. Distances and detours are geographic estimates.</p></div>`);window.RoamPhotos?.mount(p);};
function renderInbox(){$('#inbox-panel').innerHTML=`<div class="inbox-intro"><p>Every response helps me understand the difference between your usual tastes and how you feel today.</p><button class="outline-button" data-companion="sample-suggestion">Ask for a suggestion ${icon('sparkles')}</button></div><div class="inbox-list">${companion.inbox.length?companion.inbox.map(item=>{const p=places.find(p=>p.id===item.placeId),r=replyFor(item.placeId);return`<article class="inbox-item"><span class="inbox-icon">${icon(p?.event?'music':'compass')}</span><div><div class="detail-kind">${escapeHTML(item.context)} · ${new Date(item.createdAt).toLocaleDateString()}</div><h3><button data-detail="${escapeHTML(item.placeId)}">${escapeHTML(item.name)}</button></h3>${r?`<p class="response-summary">You said: ${r.feeling==='yes'?'Sounds good':r.feeling==='later'?'Not right now':r.reason==='taste'?'Not my thing':r.reason==='distance'?'Too far away':r.reason==='cost'?'Too expensive':r.reason==='crowds'?'Crowds or atmosphere':r.reason==='timing'?'Timing or energy':'Doesn’t feel right'}</p>${r.note?`<blockquote>${escapeHTML(r.note)}</blockquote>`:''}`:responseButtons(item.placeId)}<button class="text-button" data-response-detail="${escapeHTML(item.placeId)}">${r?'Update my response':'Tell me how it feels'}</button></div></article>`;}).join(''):`<div class="empty-state"><h3>Our conversation starts here.</h3><p>Ask for a suggestion or respond to a place. I’ll keep the suggestion and your feelings together.</p></div>`}</div>`;}
let serviceWorkerRegistration=null,installPrompt=null;
const serviceWorkerReady=(!window.RoamAndroid&&'serviceWorker'in navigator)?navigator.serviceWorker.register('/sw.js').then(()=>navigator.serviceWorker.ready).then(r=>{serviceWorkerRegistration=r;return r;}).catch(()=>null):Promise.resolve(null);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
function notificationStatus(){if(!('Notification'in window))return'Device notifications aren’t supported in this browser.';if(Notification.permission==='denied')return'Notifications are blocked. You can change this in your browser’s site settings.';if(Notification.permission==='granted'&&companion.notifications)return'Device notifications enabled. Suggestions can appear while Roam is running.';return'Device notifications are off. Enabling them asks for one-time browser permission.';}
settingsDialog=()=>openDialog(`<div class="dialog-inner"><div class="detail-kind">HERE, WITHOUT OVERWHELMING YOU</div><h2>A companion at your pace.</h2><p>${notificationStatus()}</p><div class="setting-row"><span>Departure-aware suggestions while Roam is open</span><input id="nudge-check" type="checkbox" aria-label="Nearby suggestions" ${state.nudges?'checked':''}></div><div class="setting-row"><span>Device notifications</span><input id="device-notifications" type="checkbox" aria-label="Device notifications" ${companion.notifications?'checked':''}></div><label class="form-label" for="notification-frequency">Suggestions per day</label><select class="form-select" id="notification-frequency">${['One thoughtful nudge','Up to three','Up to five','Only when I ask'].map(i=>`<option ${companion.answers.frequency===i?'selected':''}>${i}</option>`).join('')}</select><p class="fine-print">After a stay of about 10 minutes, repeated accurate readings beyond a 200-meter buffer confirm that you’re heading out. Your phone controls notification permission. “Sounds good” and “Not now” actions save a response; tapping a notification opens more ways to reply. Text replies open Roam. Automatic background location and remote push aren’t connected in this web version.</p><button class="dark-button full-button" data-companion="notification-settings">Save my notification preferences ${icon('bell')}</button><button class="outline-button full-button test-notification" data-companion="test-notification">Send me a test suggestion</button>${installPrompt?'<button class="text-button" data-companion="install">Install Roam on this Android phone</button>':'<p class="fine-print">Android: your browser menu may offer “Install app” or “Add to home screen.”</p>'}</div>`);
async function saveNotificationSettings(){const wantsNotifications=$('#device-notifications').checked,wantsLocation=$('#nudge-check').checked;companion.answers.frequency=$('#notification-frequency').value;if(wantsNotifications){if(!('Notification'in window)){toast('This browser doesn’t support device notifications. In-app suggestions still work.');return;}let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();if(permission!=='granted'){companion.notifications=false;persist();toast('Notifications weren’t allowed. You can still respond in the app.');return;}const registration=await serviceWorkerReady;if(!registration){toast('Device notifications couldn’t start. Try reloading the companion.');return;}companion.notifications=true;}else{companion.notifications=false;const registration=await serviceWorkerReady;if(registration){const notifications=await registration.getNotifications();notifications.forEach(n=>n.close());}}persist();$('#dialog').close();if(wantsLocation&&!state.nudges){if(state.liveLocation)startNudges();else requestLocation(true);}else if(!wantsLocation)stopNudges();toast('Your notification preferences are saved.');}
function isQuietNow(){const q=companion.answers.quiet;if(!q?.start||!q.end||q.start===q.end)return false;const time=new Date().toTimeString().slice(0,5);return q.start>q.end?(time>=q.start||time<q.end):(time>=q.start&&time<q.end);}
function mayNudge(){if(companion.answers.spontaneity==='Only when I ask'||companion.answers.frequency==='Only when I ask'||isQuietNow())return false;const count=companion.deliveries.filter(at=>new Date(at).toDateString()===new Date().toDateString()).length;const max={'One thoughtful nudge':1,'Up to three':3,'Up to five':5}[companion.answers.frequency]||3;return count<max;}
async function sendSuggestion(p,context='A suggestion for your journey',manual=false){if(!p)return;if(!manual&&!mayNudge())return;const item=ensureSuggestion(p,context);if(!manual){companion.deliveries.push(Date.now());companion.deliveries=companion.deliveries.slice(-90);companionSave();}if(companion.notifications&&'Notification'in window&&Notification.permission==='granted'){const registration=await serviceWorkerReady;if(registration){try{await registration.showNotification(p.name,{body:matchReason(p),icon:'/icon-192.png',badge:'/icon-192.png',tag:'roam-'+item.id,data:{placeId:p.id},actions:[{action:'yes',title:'Sounds good'},{action:'later',title:'Not now'},{action:'respond',title:'Tell me more'}]});item.notificationAt=Date.now();companionSave();}catch{toast('This notification couldn’t be delivered. Your suggestion is in the app.');}}}toast(`${context}: ${p.name}. You can respond in Suggestions.`);if(state.view==='inbox')renderInbox();$('#inbox-count').textContent=companion.inbox.length;}
startNudges=()=>{if(watchId!==null)navigator.geolocation.clearWatch(watchId);const departure=new RoamDeparture();state.nudges=true;watchId=navigator.geolocation.watchPosition(pos=>{state.location={name:'Your current location',lat:pos.coords.latitude,lng:pos.coords.longitude};state.liveLocation=true;const leaving=departure.update(pos.coords.latitude,pos.coords.longitude,pos.coords.accuracy,pos.timestamp);const currentView=state.view;state.view='discover';const candidates=recommendations().filter(p=>miles(p)>.16&&miles(p)<2&&(!departure.departed||distance(departure.departed,p)>.1)&&replyFor(p.id)?.feeling!=='no');state.view=currentView;if(leaving&&Date.now()-lastNudge>900000&&candidates.length&&mayNudge()){lastNudge=Date.now();sendSuggestion(candidates[0],'Heading out? One more thoughtful stop');}$('#location-label').textContent=state.location.name;if(state.view!=='profile'&&state.view!=='inbox')renderFeed();},()=>{stopNudges();toast('Location became unavailable. Nearby suggestions paused.');},{enableHighAccuracy:true,maximumAge:15000,timeout:30000});$('#nudge-toggle').innerHTML=`Departure-aware companion on ${icon('check')}`;toast('I’ll look for a good next stop when you leave somewhere after a stay.');};
function respondToButton(id,feeling){if(feeling==='no')reactionDialog(id,feeling);else{recordResponse(id,feeling);if($('#dialog').open)details(id);}}
function handleCompanionAction(b){const action=b.dataset.companion;switch(action){case'setup':if(companion.setupComplete)companion.setupIndex=0;startSetup();break;case'setup-next':saveSetupAnswer();break;case'setup-skip':saveSetupAnswer(true);break;case'setup-back':companion.setupIndex=Math.max(0,companion.setupIndex-1);companionSave();showSetupQuestion();break;case'setup-pause':$('#dialog').classList.remove('onboarding-dialog');$('#dialog').close();companionSave();render();toast('Your introduction is saved. We can pick up where you left off.');break;case'new-trip':tripDialog();break;case'save-trip':saveTrip(b.dataset.tripId);break;case'remember-route':companion.route={...locations[$('#destination').value]};state.route=companion.route;persist();render();toast('Destination remembered. Detours use geographic estimates.');break;case'import-route':importRoute($('#maps-link').value);break;case'clear-route':companion.route=null;state.route=null;persist();render();break;case'save-response':recordResponse(b.dataset.placeId,$('#reaction-feeling').value,$('#reaction-reason').value,$('#reaction-note').value.trim());$('#dialog').close();break;case'notification-settings':saveNotificationSettings();break;case'test-notification':{if(!companion.notifications){toast('Enable device notifications and save your preferences first.');return;}const p=recommendations().find(p=>!p.sample)||places[0];sendSuggestion(p,'A test from your companion',true);break;}case'sample-suggestion':{const p=recommendations().find(p=>!p.sample);if(p)sendSuggestion(p,'You asked for a suggestion',true);else toast('No nearby matches. Try a Colorado trip or a wider area.');break;}case'install':if(installPrompt){installPrompt.prompt();installPrompt=null;}break;default:return false;}return true;}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.navigation){const p=places.find(p=>p.id===b.dataset.navigation);if(p){companion.route={name:p.name,lat:p.lat,lng:p.lng};state.route=companion.route;persist();}return;}let handled=false;if(b.id==='notifications'||b.id==='nudge-toggle'){handled=true;settingsDialog();}else if(b.dataset.companion){handled=handleCompanionAction(b);}else if(b.dataset.setupChoice){handled=true;const value=b.dataset.setupChoice;if(setupCurrent.type==='multi')setupSelection=setupSelection.includes(value)?setupSelection.filter(v=>v!==value):[...setupSelection,value];else setupSelection=[value];document.querySelectorAll('[data-setup-choice]').forEach(c=>{c.classList.toggle('active',setupSelection.includes(c.dataset.setupChoice));c.setAttribute('aria-pressed',String(setupSelection.includes(c.dataset.setupChoice)));c.innerHTML=`<span>${escapeHTML(c.dataset.setupChoice)}</span>${icon(setupSelection.includes(c.dataset.setupChoice)?'check':'chevron-right')}`;});}else if(b.dataset.reply){handled=true;respondToButton(b.dataset.reply,b.dataset.feeling);}else if(b.dataset.responseDetail){handled=true;reactionDialog(b.dataset.responseDetail,'no');}else if(b.dataset.selectTrip){handled=true;companion.activeTrip=b.dataset.selectTrip;persist();render();}else if(b.dataset.editTrip){handled=true;tripDialog(b.dataset.editTrip);}else if(b.dataset.deleteTrip){handled=true;const id=b.dataset.deleteTrip;openDialog(`<div class="dialog-inner"><h2>Remove this trip?</h2><p>Your saved places and preferences will stay.</p><button class="dark-button" data-remove-trip="${id}">Remove trip</button></div>`);}else if(b.dataset.removeTrip){handled=true;companion.trips=companion.trips.filter(t=>t.id!==b.dataset.removeTrip);if(!companion.trips.some(t=>t.id===companion.activeTrip))companion.activeTrip=companion.trips[0]?.id||null;persist();$('#dialog').close();render();}else if(b.id==='personalize'){handled=true;if(companion.setupComplete)companion.setupIndex=0;startSetup();}if(handled){e.preventDefault();e.stopImmediatePropagation();}},true);
$('#dialog').addEventListener('close',()=>$('#dialog').classList.remove('onboarding-dialog'));
async function consumePendingResponses(){if(!('indexedDB'in window))return;const db=await new Promise((resolve,reject)=>{const request=indexedDB.open('roam-notification-responses',1);request.onupgradeneeded=()=>request.result.createObjectStore('responses',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});try{const replies=await new Promise((resolve,reject)=>{const req=db.transaction('responses').objectStore('responses').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});for(const reply of replies){if(recordResponse(reply.placeId,reply.feeling)){await new Promise((resolve,reject)=>{const tx=db.transaction('responses','readwrite');tx.objectStore('responses').delete(reply.id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}}}finally{db.close();}}
if('serviceWorker'in navigator)navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='ROAM_RESPONSE')consumePendingResponses().catch(()=>{});if(e.data?.type==='ROAM_OPEN_SUGGESTION')details(e.data.placeId);});
window.addEventListener('focus',()=>consumePendingResponses().catch(()=>{}));
async function loadEvents(){try{const response=await fetch('/events.json');if(!response.ok)throw new Error('Event listing unavailable');const data=await response.json();if(!Array.isArray(data.events))throw new Error('Invalid listing');for(const p of data.events){if(p.id&&p.event&&p.start&&p.sourceURL&&new URL(p.sourceURL).hostname==='www.redrocksonline.com'&&!places.some(x=>x.id===p.id))places.push(p);}if(Array.isArray(stored.saved))state.saved=[...new Set([...state.saved,...stored.saved.filter(id=>places.some(p=>p.id===id))])];companion.eventStatus='ready';}catch{companion.eventStatus='error';}render();await consumePendingResponses().catch(()=>{});const params=new URLSearchParams(location.search);if(params.get('suggestion')&&places.some(p=>p.id===params.get('suggestion')))details(params.get('suggestion'));if(params.has('share_url')||params.has('share_text')){const text=[params.get('share_url'),params.get('share_text')].filter(Boolean).join(' ');const parsed=parseMapsDestination(text);if(!parsed.unsupported&&!parsed.address){importRoute(text);}else{changeView('route');$('#maps-link').value=text;toast('Your shared link is here. Choose an area or use a full destination link.');}history.replaceState({},'',location.pathname);}else if(!companion.setupComplete&&!params.has('suggestion'))startSetup();}
if(companion.route)state.route=companion.route;
hydrate();render();loadEvents();
